#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "symm.h"

/* Include the Exo-generated kernel header. */
#include "generated/symm/symm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
      B[i][j] = (DATA_TYPE) ((n+i-j) % 100) / m;
    }
  for (i = 0; i < m; i++) {
    for (j = 0; j <=i; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
    for (j = i+1; j < m; j++)
      A[i][j] = -999; //regions of arrays that should not be used
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable tile size for the column (j) dimension.
# This is a compile-time constant that can be adjusted for the target hardware.
TJ = 64


@proc
def kernel_symm(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[m, n] @ DRAM,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    # Basic sanity: we operate on the full m x n domain.
    assert m >= 1
    assert n >= 1

    # Reformulated SYMM kernel with better structure for scheduling.
    # Mathematically equivalent to the original PolyBench kernel:
    #
    #   for i in 0..m-1:
    #     for j in 0..n-1:
    #       temp2 = 0
    #       for k in 0..i-1:
    #         C[k,j] += alpha * B[i,j] * A[i,k]
    #         temp2  +=          B[k,j] * A[i,k]
    #       C[i,j] = beta * C[i,j] + alpha * B[i,j] * A[i,i] + alpha * temp2
    #
    # The code below performs the same computation but separates:
    #   * Row-wise scaling by beta and the diagonal term A[i,i] * B[i,j]
    #   * The symmetric off-diagonal updates that only use reductions (+=)

    for i in seq(0, m):

        # 1) Scale row i of C by beta and add the diagonal contribution
        #    alpha * B[i,j] * A[i,i]. This matches the "beta * C + diag" part.
        for j in seq(0, n):
            C[i, j] = beta * C[i, j] + alpha * B[i, j] * A[i, i]

        # 2) Symmetric update for all rows k < i.
        #    Using the symmetry of A (stored in its lower triangle), for each
        #    k < i and all j we add:
        #      C[k,j] += alpha * B[i,j] * A[i,k]
        #      C[i,j] += alpha * B[k,j] * A[i,k]
        #
        #    The first line accumulates contributions to rows k < i from row i.
        #    The second line accumulates the "temp2" contribution directly into
        #    C[i,j] instead of using a temporary scalar.
        for k in seq(0, i):
            a_ik: DATA_TYPE
            a_ik = A[i, k]

            # j is the fastest-varying index, giving row-major, contiguous
            # accesses for C[* , j] and B[* , j].
            for j in seq(0, n):
                C[k, j] += alpha * B[i, j] * a_ik
                C[i, j] += alpha * B[k, j] * a_ik


# ---------------------------------------------------------------------------
# Scheduling: tile the j (column) dimension for better cache locality and
#             to expose short inner loops that are amenable to vectorization.
# ---------------------------------------------------------------------------

# Tile the j-loop in the beta/diagonal row update:
j_diag = kernel_symm.find_loop("j")
kernel_symm = divide_loop(
    kernel_symm,
    j_diag,
    TJ,
    ("jo", "ji"),
    tail="guard",
)

# Tile the j-loop inside the symmetric update (the j-loop inside the k-loop):
k_loop = kernel_symm.find_loop("k")
j_symm = k_loop.body().find_loop("j")
kernel_symm = divide_loop(
    kernel_symm,
    j_symm,
    TJ,
    ("jo2", "ji2"),
    tail="guard",
)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_symm (/*ctxt=*/NULL, m, n,
	       (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	       (DATA_TYPE*)POLYBENCH_ARRAY(C),
	       (DATA_TYPE*)POLYBENCH_ARRAY(A),
	       (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
