def symm_unoptimized(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[m, n] @ DRAM,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    # Symmetric matrix-matrix multiply (lower triangle of A is used).
    for i in seq(0, m):
        for j in seq(0, n):
            temp2: DATA_TYPE
            temp2 = 0
            for k in seq(0, i):
                # C[k, j] accumulates contributions from row i / column k.
                C[k, j] += alpha * B[i, j] * A[i, k]
                # temp2 accumulates the symmetric part using B[k, j].
                temp2 += B[k, j] * A[i, k]
            # Final update for the diagonal element C[i, j].
            C[i, j] = beta * C[i, j] + alpha * B[i, j] * A[i, i] + alpha * temp2


# -------------------- Scheduling --------------------

p = symm_unoptimized

# 1) Hoist the common product alpha * B[i, j] into a scalar temporary.
#    This avoids recomputing the same product inside the inner k-loop and
#    makes the generated C code more amenable to compiler optimization.
alpha_bij_exprs = p.find_all("alpha * B[i, j]")
p = bind_expr(p, alpha_bij_exprs, "alpha_Bij")

# 2) Tile the column dimension j to improve cache locality and to expose
#    a coarse-grain parallel loop over column blocks.
#
#    After this transformation, the loop nest shape (ignoring k) is:
#      for i in 0..m:
#        for j_outer in 0..ceil(n / J_BLOCK):
#          for j_inner in 0..J_BLOCK:
#            if j is in-bounds:
#               ...
p = divide_loop(p, "j", J_BLOCK, ["j_outer", "j_inner"], tail="guard")

# 3) Reorder loops so that the outer j-tile loop becomes the outermost loop.
#    All operations on different columns j are independent: each iteration
#    only reads A and touches C[:, j] and B[:, j]. Therefore, reordering
#    (i, j_outer) is semantics-preserving.
p = reorder_loops(p, "i j_outer")

# 4) Parallelize the outermost j-tile loop. Each tile operates on a disjoint
#    set of columns of B and C and only reads A, so there are no dependencies
#    across j_outer iterations.
p = parallelize_loop(p, "j_outer")

# 5) Simplify the resulting code (clean up guards, expressions, etc.).
p = simplify(p)

# Export the scheduled kernel under the expected name.
kernel_symm = rename(p, "kernel_symm")
